def clean(df):
    out = df.copy()
    out = out.drop_duplicates()
    if 'Category' in out.columns:
        out['Category'] = out['Category'].astype('string').str.strip().replace({'Furnture': 'Furniture'})
    if 'Region' in out.columns:
        out['Region'] = out['Region'].astype('string').str.strip()
        out.loc[out['Region'].isin(['']), 'Region'] = pd.NA
    for col in ['Quantity', 'Price', 'Revenue']:
        if col in out.columns:
            out[col] = pd.to_numeric(out[col], errors='coerce')
    return out

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Category', 'Price'])
    result = d.groupby('Category', dropna=True)['Price'].mean()
    return {str(k): float(v) for k, v in result.items()}
